-- mod-temucraft-models: generated by tools/gen_models.py, do not edit by hand.
-- Display rows, showcase creatures and fully cosmetic items for models that ship in the Temucraft client patches
-- but had no display row, plus cosmetic outfits from city guards. Ids are the variables below; every block deletes its
-- own range first, so the file can be run again. The client needs the same rows (client/DBFilesClient).
SET @CMD  := 46000; -- CreatureModelData
SET @CDI  := 1210000; -- CreatureDisplayInfo
SET @IDI  := 1210000; -- ItemDisplayInfo
SET @CRE  := 1210000; -- creature_template
SET @ITEM := 1210000; -- item_template, Item.dbc (looks from the free models)
SET @OUT  := 1220000; -- item_template, Item.dbc (NPC outfits)
SET @ODI  := 1220000; -- ItemDisplayInfo (NPC looks given an icon)
SET @SET  := 4000; -- ItemSet (one per outfit)

DELETE FROM `creaturemodeldata_dbc` WHERE `ID` BETWEEN @CMD AND @CMD+2999;


DELETE FROM `creaturedisplayinfo_dbc` WHERE `ID` BETWEEN @CDI AND @CDI+9999;


DELETE FROM `creature_model_info` WHERE `DisplayID` BETWEEN @CDI AND @CDI+9999;


DELETE FROM `creature_template_model` WHERE `CreatureID` BETWEEN @CRE AND @CRE+9999;

DELETE FROM `creature_template` WHERE `entry` BETWEEN @CRE AND @CRE+9999;



DELETE FROM `itemdisplayinfo_dbc` WHERE `ID` BETWEEN @IDI AND @IDI+9999;


DELETE FROM `itemdisplayinfo_dbc` WHERE `ID` BETWEEN @ODI AND @ODI+39999;


DELETE FROM `item_loot_template` WHERE `Entry` BETWEEN @ITEM AND @ITEM+9999;

DELETE FROM `item_dbc` WHERE `ID` BETWEEN @ITEM AND @ITEM+9999;

DELETE FROM `item_template` WHERE `entry` BETWEEN @ITEM AND @ITEM+9999;

DELETE FROM `item_loot_template` WHERE `Entry` BETWEEN @OUT AND @OUT+39999;

DELETE FROM `item_dbc` WHERE `ID` BETWEEN @OUT AND @OUT+39999;

DELETE FROM `item_template` WHERE `entry` BETWEEN @OUT AND @OUT+39999;




DELETE FROM `itemset_dbc` WHERE `ID` BETWEEN @SET AND @SET+2999;

